package cn.zhigeng.app;
import android.app.*;import android.os.*;import android.net.Uri;import android.graphics.*;import android.graphics.pdf.PdfRenderer;import android.widget.*;

/** PDF viewing remains inside Zhigeng, using Android's PDF renderer. */
public class PdfActivity extends Activity {
    private PdfRenderer renderer;private ParcelFileDescriptor fd;private ImageView image;private TextView number;private int page=0;private String id;private Bitmap bitmap;
    @Override public void onCreate(Bundle state){super.onCreate(state);LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(0xfff7f5ef);LinearLayout bar=new LinearLayout(this);Button back=new Button(this);back.setText("返回书架");back.setOnClickListener(v->finish());bar.addView(back);number=new TextView(this);bar.addView(number,new LinearLayout.LayoutParams(0,-2,1));Button prev=new Button(this);prev.setText("上一页");bar.addView(prev);Button next=new Button(this);next.setText("下一页");bar.addView(next);root.addView(bar);ScrollView scroll=new ScrollView(this);image=new ImageView(this);image.setAdjustViewBounds(true);scroll.addView(image);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);try{id=getIntent().getStringExtra("uri");fd=getContentResolver().openFileDescriptor(Uri.parse(id),"r");renderer=new PdfRenderer(fd);page=Math.min(getSharedPreferences("reader",MODE_PRIVATE).getInt(id+":pdfPage",0),renderer.getPageCount()-1);show();}catch(Exception e){new AlertDialog.Builder(this).setMessage("PDF 打开失败，请检查文件或重新导入。").setPositiveButton("返回",(d,w)->finish()).show();}prev.setOnClickListener(v->{if(renderer!=null&&page>0){page--;show();}});next.setOnClickListener(v->{if(renderer!=null&&page<renderer.getPageCount()-1){page++;show();}});}
    private void show(){try(PdfRenderer.Page p=renderer.openPage(page)){int width=Math.min(1400,getResources().getDisplayMetrics().widthPixels),height=Math.min(6000,Math.max(1,Math.round(width*p.getHeight()/(float)p.getWidth())));Bitmap next=Bitmap.createBitmap(width,height,Bitmap.Config.ARGB_8888);next.eraseColor(Color.WHITE);p.render(next,null,null,PdfRenderer.Page.RENDER_MODE_FOR_DISPLAY);image.setImageBitmap(next);if(bitmap!=null)bitmap.recycle();bitmap=next;number.setText((page+1)+" / "+renderer.getPageCount());getSharedPreferences("reader",MODE_PRIVATE).edit().putInt(id+":pdfPage",page).apply();}catch(Exception e){Toast.makeText(this,"该页无法显示",0).show();}}
    @Override protected void onDestroy(){if(renderer!=null)renderer.close();try{if(fd!=null)fd.close();}catch(Exception ignored){}super.onDestroy();}
}
